    """Canonical JSON bytes. No trailing newline, no BOM, no whitespace."""
    text = _encode(value, depth=1)
    raw = text.encode("utf-8")
    if len(raw) > MAX_BYTES:
        raise AdmissionError("DESCRIPTOR_TOO_LARGE", f"C(X) {len(raw)} exceeds 4 MiB")
