)

PROCESS_FAULT_FRAMES = set(DOC["wildcards"]["*PROCESS_FAULT"]["frames"])
PRE_COMPLETE = set(DOC["wildcards"]["*PRE_COMPLETE"]["phases"])
SOURCE_BYTE_FRAMES = {
    "DependencySourceChunk",
    "DependencySourceManifest",
    "OpenUniverse",
    "PreparedOutputChunk",
    "PreparedOutputManifest",
    "SnapshotFileChunk",
